MP="py -3.13 <your-picture-maker>/make-picture.py"
STY="Classic American comic-book panel illustration: bold black ink outlines of the same weight, Ben-Day halftone dot shading, flat vivid colours in a warm palette of warm yellows, peanut-butter browns and sky-blue accents, dynamic angle, comic motion lines. No text, no lettering, no speech bubbles, no sound-effect words, no people, no faces."
NEG="text, letters, words, lettering, speech bubble, caption box, sound effect words, onomatopoeia, signature, watermark, logo, label text, face, head, eyes, person, blurry, low quality, photo, photorealistic, 3d render, extra fingers, missing fingers, distorted hands, deformed knife, panel border, multiple panels"
O=assets_work/comic
$MP "$STY Scene: top-down view of two slices of white sandwich bread with golden-brown crusts lying side by side on a wooden cutting board on a kitchen counter, sky-blue tiles at the edges of the frame." $O/cm1 --size 1328x1328 --n 4 --seed 1101 --negative "$NEG"
$MP "$STY Scene: dramatic low-angle close-up of one human hand plunging a butter knife into an open glass jar full of creamy tan-brown peanut butter, action lines bursting outward, only the hand and wrist visible, plain jar with no label." $O/cm2 --size 1328x1328 --n 4 --seed 1201 --negative "$NEG"
$MP "$STY Scene: one human hand spreading thick creamy tan-brown peanut butter with a butter knife across a slice of white bread right to the crust edges, curved motion lines following the knife." $O/cm3 --size 1664x928 --n 4 --seed 1301 --negative "$NEG"
$MP "$STY Scene: two human hands pressing the top slice of bread down onto a peanut butter sandwich on a cutting board, squash and impact lines radiating outward, peanut butter bulging a little at the edges." $O/cm4 --size 1328x1328 --n 4 --seed 1401 --negative "$NEG"
$MP "$STY Scene: a big chef's knife slicing a peanut butter sandwich diagonally from corner to corner on a wooden cutting board, strong speed lines, dramatic low camera angle." $O/cm5 --size 1664x928 --n 4 --seed 1501 --negative "$NEG"
$MP "$STY Scene: hero shot of two triangle peanut butter sandwich halves on a white plate, the tan-brown filling visible on the cut edges, sparkles around them, a yellow and orange sunburst of rays in the background." $O/cm6 --size 1664x928 --n 4 --seed 1601 --negative "$NEG"
